UISpawnZoneSparkEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,100);this.particleClass=UISparkParticle;this.makeParticles('game',['spawnSpark0','spawnSpark1']);this.particleDrag.setTo(100,100);this.setAlpha(0.6,0.8);this.setRotation(0,0);this.minParticleScale=UIConstants.GAME_ASSET_SCALE*0.8;this.maxParticleScale=UIConstants.GAME_ASSET_SCALE;this.gravity=0;this.kill();this.visible=false;};UISpawnZoneSparkEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UISpawnZoneSparkEmitter.prototype.constructor=UISpawnZoneSparkEmitter;UISpawnZoneSparkEmitter.prototype.preUpdate=function(){if(!this.exists||this.game.physics.arcade.isPaused){return false;}return Phaser.Particles.Arcade.Emitter.prototype.preUpdate.call(this);};UISpawnZoneSparkEmitter.prototype.update=function(){if(!this.exists||this.game.physics.arcade.isPaused){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);if(this.countLiving()==0){this.kill();this.visible=false;}};UISpawnZoneSparkEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UISpawnZoneSparkEmitter.prototype.emit=function(radius,speedModifier,count){this.revive();this.visible=true;var rotation=Math.random()*2*Math.PI;var speedX=Math.cos(rotation)*UIConstants.SPAWN_ZONE_SPARK_SPEED*speedModifier;var speedY=Math.sin(rotation)*UIConstants.SPAWN_ZONE_SPARK_SPEED*speedModifier;var posX=Math.cos(rotation)*radius;var posY=Math.sin(rotation)*radius;this.minParticleSpeed.setTo(speedX-UIConstants.SPAWN_ZONE_SPARK_RANDOM_SPEED,speedY-UIConstants.SPAWN_ZONE_SPARK_RANDOM_SPEED);this.maxParticleSpeed.setTo(speedX+UIConstants.SPAWN_ZONE_SPARK_RANDOM_SPEED,speedY+UIConstants.SPAWN_ZONE_SPARK_RANDOM_SPEED);this.emitX=posX;this.emitY=posY;this.explode(1200,count);};UISpawnZoneSparkEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};